package org.brightstats.desktop;

import java.util.*;
import javafx.geometry.Insets;
import javafx.scene.control.*;
import javafx.scene.layout.VBox;
import javafx.stage.Window;
import org.brightstats.stats.*;

final class TetradDialog {
    private final Dialog<TetradAnalysis.Options> dialog=new Dialog<>();private final TextField samples=new TextField(),seed=new TextField(),significance=new TextField();private final ComboBox<RegressionBootstrap.Convention> convention=new ComboBox<>();private final ComboBox<TetradAnalysis.Selection> selection=new ComboBox<>();private final CheckBox twoSided=new CheckBox("Two-sided inference"),retain=new CheckBox("Retain every bootstrap tetrad value in saved results");private TetradAnalysis.Options result;
    TetradDialog(Window owner,TetradAnalysis.Options previous,List<PlsSem.Block> blocks){
        var options=previous==null?TetradAnalysis.Options.defaults():previous;dialog.initOwner(owner);dialog.setTitle("Confirmatory tetrad analysis");samples.setText(Integer.toString(options.samples()));seed.setText(Long.toString(options.seed()));significance.setText(Double.toString(options.significance()));convention.getItems().setAll(RegressionBootstrap.Convention.values());convention.setValue(options.convention());selection.getItems().setAll(TetradAnalysis.Selection.values());selection.setValue(options.selection());twoSided.setSelected(options.twoSided());retain.setSelected(options.retainDraws());Label explanation=UiAppearance.label("Each 4–25-indicator block is assessed from its raw covariance tetrads. Shorter/larger blocks are listed as skipped. A PLS fit is not required. Bonferroni correction applies within each block. Nonrejection does not prove a reflective specification; review theory and degeneracy. Reference one-tailed mode retains its sign-adaptive/symmetric-interval behavior.");explanation.setWrapText(true);Label available=new Label(String.join("\n",blocks.stream().map(block->block.name()+": "+block.columns().length+" indicators"+(block.columns().length<4||block.columns().length>25?" (skipped)":"")).toList()));available.setWrapText(true);Label error=new Label();error.setWrapText(true);VBox content=new VBox(8,explanation,available,UiAppearance.label("Bootstrap samples"),samples,UiAppearance.label("Random seed"),seed,UiAppearance.label("Significance level"),significance,UiAppearance.label("Inference and row-sampling convention"),convention,UiAppearance.label("Tetrad selection"),selection,twoSided,retain,error);content.setPadding(new Insets(12));ScrollPane scroll=new ScrollPane(content);scroll.setFitToWidth(true);scroll.setPrefSize(650,650);dialog.getDialogPane().setContent(scroll);dialog.setResizable(true);dialog.getDialogPane().getButtonTypes().setAll(ButtonType.OK,ButtonType.CANCEL);dialog.getDialogPane().lookupButton(ButtonType.OK).addEventFilter(javafx.event.ActionEvent.ACTION,event->{result=null;try{if(blocks.stream().noneMatch(block->block.columns().length>=4&&block.columns().length<=25))throw new IllegalArgumentException("Assign at least four indicators to a block before tetrad analysis.");result=new TetradAnalysis.Options(Integer.parseInt(samples.getText().trim()),Long.parseLong(seed.getText().trim()),Double.parseDouble(significance.getText().trim()),convention.getValue(),twoSided.isSelected(),selection.getValue(),retain.isSelected());}catch(Exception problem){event.consume();error.setText(problem.getMessage());}});dialog.setResultConverter(button->button==ButtonType.OK?result:null);
    }
    static Optional<TetradAnalysis.Options> show(Window owner,TetradAnalysis.Options previous,List<PlsSem.Block> blocks){return new TetradDialog(owner,previous,blocks).dialog.showAndWait();}
    static TetradAnalysis.Options smokeTest(Window owner,List<PlsSem.Block> blocks){var test=new TetradDialog(owner,null,blocks);test.dialog.show();test.samples.setText("29");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Too few tetrad samples accepted");test.samples.setText("40");test.significance.setText("0");((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Invalid tetrad significance accepted");test.significance.setText("0.05");test.twoSided.setSelected(false);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(!test.dialog.isShowing()||test.result!=null)throw new AssertionError("Standard adaptive one-tail inference accepted");test.twoSided.setSelected(true);test.retain.setSelected(true);((Button)test.dialog.getDialogPane().lookupButton(ButtonType.OK)).fire();if(test.dialog.getResult()==null)throw new AssertionError("Tetrad settings lost");return test.dialog.getResult();}
}
